'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict'),path=require('node:path');
const d='docs/papers211_215_sequence/scouting/finite_resource_rewriting_desk02';
const expected=['INPUT_PINS.sha256','LOCAL_NATIVE_RECORDS.json','PRIMARY_SOURCE_RECORDS.json','REPORT.md'];
assert.deepEqual(fs.readdirSync(d).sort(),expected);
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const native=JSON.parse(fs.readFileSync(path.join(d,'LOCAL_NATIVE_RECORDS.json'),'utf8'));
const web=JSON.parse(fs.readFileSync(path.join(d,'PRIMARY_SOURCE_RECORDS.json'),'utf8'));
assert.equal(native.record_count,12);
assert.equal(native.records.length,12);
assert.deepEqual(native.mixed_pointer_content_exposure_record_indices,[6,7]);
assert.equal(web.browser_request_count,3);
assert.equal(web.requests.length,3);
assert.equal(native.scientific_runs,0);
assert.equal(web.scientific_executions,0);
const allowedOriginals=[
 'docs/papers204_208_sequence/scouting/combinatorial_second/PROOF_NOTES.md',
 'docs/papers204_208_sequence/scouting/combinatorial_second/SOURCE_AND_COLLISION_NOTES.md'
];
const pinRows=fs.readFileSync(path.join(d,'INPUT_PINS.sha256'),'utf8').trim().split('\n');
assert.equal(pinRows.length,2);
const originalPins=pinRows.map((line,i)=>{
 const m=/^([0-9a-f]{64})  (.+)$/.exec(line);assert(m);
 assert.equal(m[2],allowedOriginals[i]);
 const b=fs.readFileSync(m[2]);assert.equal(sha(b),m[1]);
 return {path:m[2],sha256:m[1],bytes:b.length,operation:'MACHINE_HASH_ONLY_NO_BODY_DISPLAY'};
});
const comparisons=[[6,10,24,81],[7,11,20,33]].map(([first,repeat,lo,hi])=>{
 const a=native.records[first],b=native.records[repeat];
 const selected=Buffer.from(a.output.split('\n').slice(lo-1,hi).join('\n')+'\n','utf8');
 const actual=Buffer.from(b.output,'utf8');
 assert(selected.equals(actual));
 return {archived_mixed_record:first,section_only_repeat_record:repeat,lines:[lo,hi],bytes:actual.length,sha256:sha(actual),actual_repeat_native_chunk:b.chunk_id};
});
const exposures=[6,7].map(i=>({record_index:i,native_chunk:native.records[i].chunk_id,retained_return_bytes:Buffer.byteLength(native.records[i].output),mathematical_use:'ZR SECTION ONLY; PR EXPOSURE DISCLOSED'}));
const inventory=expected.map(name=>{const b=fs.readFileSync(path.join(d,name));return{name,bytes:b.length,sha256:sha(b)};});
process.stdout.write(JSON.stringify({status:'PASS_DOCUMENTARY_ONLY',scientific_executions:0,first_four_payload_inventory:inventory,first_four_payload_bytes:inventory.reduce((n,x)=>n+x.bytes,0),selected_original_pins:originalPins,two_actual_ZR_byte_comparisons:comparisons,mixed_read_exposures_preserved:exposures,construction_parse_failure_preserved:native.document_construction_failure,limitations:['Post-read pins, not a scientific prelock.','Only two selected original full-file hashes are checked; discovery is not a complete dependency key.','Combined decoded tool returns, not independent raw stdout/stderr streams.','The checks do not import or execute any scientific implementation.','No source-body or theorem truth is inferred from a hash.']},null,2)+'\n');
NODE

